syntax:
For a struct managing dynamic memory:

void struct_cleanup(struct MyStruct *obj) {
    if (obj->pointer_member != NULL) {
        free(obj->pointer_member);
        obj->pointer_member = NULL;
    }
}

code_example:
typedef struct {
    int *data;
} MyStruct;

MyStruct *create_struct() {
    MyStruct *s = malloc(sizeof(MyStruct));
    s->data = malloc(100 * sizeof(int)); // allocate dynamic memory
    return s;
}

void destroy_struct(MyStruct *s) {
    if (s != NULL) {
        free(s->data); // explicitly free allocated memory
        free(s);
    }
}
